const acts = {}, forms = {}, changes = {}, inputs = {};
const $ = (s, r = document) => r.querySelector(s);
const $$ = (s, r = document) => Array.from(r.querySelectorAll(s));
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const uid = () => Math.random().toString(36).slice(2, 10);
const nowIso = () => new Date().toISOString();
const daysAgo = d => new Date(Date.now() - d * 864e5).toISOString();
const hoursAhead = h => new Date(Date.now() + h * 36e5).toISOString();
const fmt = iso => (iso ? new Date(iso).toLocaleString('en-PH', { dateStyle: 'medium', timeStyle: 'short' }) : '—');
const localInput = iso => { const d = new Date(iso || Date.now()); d.setMinutes(d.getMinutes() - d.getTimezoneOffset()); return d.toISOString().slice(0, 16); };
const ago = iso => {
  const m = Math.round((Date.now() - new Date(iso)) / 6e4);
  if (m < 1) return 'just now';
  if (m < 60) return `${m} min ago`;
  const h = Math.round(m / 60);
  return h < 24 ? `${h} h ago` : `${Math.round(h / 24)} d ago`;
};
const kmBetween = (a, b) => {
  const R = 6371, t = x => (x * Math.PI) / 180;
  const dA = t(b[0] - a[0]), dO = t(b[1] - a[1]);
  const h = Math.sin(dA / 2) ** 2 + Math.cos(t(a[0])) * Math.cos(t(b[0])) * Math.sin(dO / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(h));
};
const firstName = u => (u.name || '').split(' ')[0];
const shortName = u => { const p = (u.name || '').split(' ').filter(Boolean); return p.length > 1 ? `${p[0]} ${p[p.length - 1][0]}.` : p[0] || ''; };
const isUrgent = p => new Date(p.neededBy) - Date.now() < 864e5;
const readFile = (file, done) => {
  if (!file) return;
  if (!/^image\//.test(file.type) || file.size > 2e6) return toast('Choose an image under 2 MB.', 'error');
  const r = new FileReader();
  r.onload = () => done(r.result);
  r.readAsDataURL(file);
};

