/* ============ 4. Forms, validation, modal, toast ============ */
const opt = (list, cur) => list.map(x => `<option value="${esc(x)}" ${String(x) === String(cur) ? 'selected' : ''}>${esc(x)}</option>`).join('');
const v = (f, n) => (f.elements[n] ? f.elements[n].value ?? '' : '');
const chk = (f, n) => !!f.elements[n]?.checked;
const V = {
  req: x => x !== '' && x != null && x !== false,
  check: x => x === true,
  email: x => /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(x),
  pw: x => /^(?=.*[A-Za-z])(?=.*\d).{8,}$/.test(x),
  phone: x => /^(\+?63|0)9\d{9}$/.test(String(x).replace(/[\s-]/g, '')),
  future: x => !!x && new Date(x) > new Date(),
  pos: x => x === '' || Number(x) >= 1,
};

function field(label, name, o = {}) {
  const { type = 'text', value = '', required = false, placeholder = '', hint = '', options = null, attrs = '' } = o;
  const req = required ? 'required' : '';
  let control;
  if (type === 'select') control = `<select name="${name}" ${req} ${attrs}>${opt(options, value)}</select>`;
  else if (type === 'textarea') control = `<textarea name="${name}" rows="3" placeholder="${esc(placeholder)}" ${req} ${attrs}>${esc(value)}</textarea>`;
  else control = `<input type="${type}" name="${name}" value="${esc(value)}" placeholder="${esc(placeholder)}" ${req} ${attrs}>`;
  return `<label class="field"><span>${esc(label)}${required ? ' <em>*</em>' : ''}</span>${control}${hint ? `<small class="hint">${esc(hint)}</small>` : ''}<small class="err" data-err="${name}"></small></label>`;
}
function pwField(label, name, hint = '') {
  return `<label class="field"><span>${esc(label)} <em>*</em></span><div class="pw"><input type="password" name="${name}" autocomplete="new-password" required><button type="button" class="pw-toggle" data-act="toggle-pw" aria-label="Show password" aria-pressed="false">${icon('eye', 20)}</button></div>${hint ? `<small class="hint">${esc(hint)}</small>` : ''}<small class="err" data-err="${name}"></small></label>`;
}
function cityControl(r, p, cur = '') {
  const list = cities(r, p);
  return list.length
    ? `<select name="city" required>${opt(list, cur)}</select>`
    : `<input name="city" value="${esc(cur)}" placeholder="City or municipality" required>`;
}
function locFields(loc = {}) {
  const r = PH[loc.region] ? loc.region : regions()[0];
  const p = PH[r][loc.province] ? loc.province : provinces(r)[0];
  return `<div class="grid-2">
    <label class="field"><span>Region <em>*</em></span><select name="region" data-change="loc-region">${opt(regions(), r)}</select></label>
    <label class="field"><span>Province <em>*</em></span><select name="province" data-change="loc-province">${opt(provinces(r), p)}</select></label>
    <label class="field"><span>City / Municipality <em>*</em></span><div data-city-slot>${cityControl(r, p, loc.city || '')}</div><small class="err" data-err="city"></small></label>
    <label class="field"><span>Barangay <em>*</em></span><input name="barangay" value="${esc(loc.barangay || '')}" required><small class="err" data-err="barangay"></small></label>
  </div>`;
}
function refreshCity(f) {
  const slot = f.querySelector('[data-city-slot]');
  if (slot) slot.innerHTML = cityControl(f.elements.region.value, f.elements.province.value);
}
changes['loc-region'] = el => {
  const f = el.form, r = el.value;
  f.elements.province.innerHTML = opt(provinces(r), provinces(r)[0]);
  refreshCity(f);
};
changes['loc-province'] = el => refreshCity(el.form);

function bloodSelect(cur, label = 'Blood type') {
  return `<label class="field"><span>${label} <em>*</em></span><select name="bloodType" required><option value="">Choose…</option>${opt(BLOOD_TYPES, cur)}</select><small class="err" data-err="bloodType"></small></label>`;
}
const readLoc = f => ({ region: v(f, 'region'), province: v(f, 'province'), city: v(f, 'city'), barangay: v(f, 'barangay').trim() });

function validate(form, checks) {
  const failed = new Set();
  $$('.err', form).forEach(e => (e.textContent = ''));
  for (const [name, test, msg] of checks) {
    if (failed.has(name)) continue;
    const el = form.elements[name];
    if (!el) continue;
    const val = el.type === 'checkbox' ? el.checked : typeof el.value === 'string' ? el.value.trim() : el.value;
    if (!test(val, form)) {
      failed.add(name);
      const err = $(`[data-err="${name}"]`, form);
      if (err) err.textContent = msg;
    }
  }
  if (failed.size) {
    toast('Please fix the highlighted fields.', 'error');
    $(`[data-err="${[...failed][0]}"]`, form)?.closest('label')?.querySelector('input,select,textarea')?.focus();
    return false;
  }
  return true;
}
function formAlert(f, msg) {
  let a = f.querySelector('.form-alert');
  if (!a) { a = document.createElement('p'); a.className = 'form-alert'; a.setAttribute('role', 'alert'); f.prepend(a); }
  a.textContent = msg;
}

let toastTimer2 = null;
function toast(msg, type = 'ok') {
  const t = $('#toast');
  t.textContent = msg;
  t.className = `toast show ${type}`;
  clearTimeout(toastTimer2);
  toastTimer2 = setTimeout(() => t.classList.remove('show'), 3200);
}
function openModal(title, body, { submit = null, label = 'Save', danger = false } = {}) {
  modalSubmit = submit;
  const m = $('#modal');
  m.innerHTML = `
    <div class="sheet" role="dialog" aria-modal="true" aria-labelledby="modal-title">
      <header class="sheet-head"><h2 id="modal-title">${esc(title)}</h2><button type="button" class="icon-btn" data-act="close-modal" aria-label="Close">${icon('x')}</button></header>
      <form class="sheet-body" data-form="modal" novalidate>
        ${body}
        <footer class="sheet-foot">
          <button type="button" class="btn ghost" data-act="close-modal">${submit ? 'Cancel' : 'Close'}</button>
          ${submit ? `<button type="submit" class="btn ${danger ? 'danger' : 'primary'}">${esc(label)}</button>` : ''}
        </footer>
      </form>
    </div>`;
  m.hidden = false;
  requestAnimationFrame(() => m.classList.add('open'));
  $('input,select,textarea,button', m)?.focus();
}
function closeModal() {
  const m = $('#modal');
  m.classList.remove('open');
  modalSubmit = null;
  setTimeout(() => { if (!m.classList.contains('open')) { m.hidden = true; m.innerHTML = ''; } }, 180);
}
function confirmBox(title, msg, label, fn) {
  openModal(title, `<p>${esc(msg)}</p>`, { label, danger: true, submit: () => { fn(); closeModal(); } });
}
function dl(rows) {
  return `<dl class="kv">${rows.map(([k, val]) => `<div><dt>${esc(k)}</dt><dd>${esc(val ?? '—')}</dd></div>`).join('')}</dl>`;
}
function detailsList(p) {
  if (p.type === 'request') return [['Patient', p.patient], ['Blood type', p.bloodType], ['Units', p.units || 'Not specified'], ['Hospital', p.hospital], ['Location', placeText(p.loc)], ['Needed by', fmt(p.neededBy)], ['Contact', p.contact], ['Situation', p.description || '—'], ['Photo', p.photoName ? `${p.photoName} (consent recorded)` : 'None']];
  if (p.type === 'availability') return [['Blood type', p.bloodType], ['Service radius', `${p.radius} km`], ['Availability', p.availability], ['Contact preference', p.contactPref], ['Location', placeText(p.loc)], ['Notes', p.notes || '—']];
  if (p.type === 'event') return [['Title', p.title], ['Date', fmt(p.eventDate)], ['Venue', p.venue], ['Location', placeText(p.loc)], ['Details', p.description || '—']];
  return [['Title', p.title], ['Message', p.body]];
}

/* ============ 5. Action registry (event delegation) ============ */
document.addEventListener('click', e => {
  const el = e.target.closest('[data-act]');
  if (!el) return;
  const fn = acts[el.dataset.act];
  if (fn) { e.preventDefault(); fn(el, e); }
});
document.addEventListener('submit', e => {
  const f = e.target;
  if (!f.dataset.form) return;
  e.preventDefault();
  forms[f.dataset.form]?.(f);
});
document.addEventListener('change', e => { const el = e.target; if (el.dataset.change) changes[el.dataset.change]?.(el); });
document.addEventListener('input', e => { const el = e.target; if (el.dataset.input) inputs[el.dataset.input]?.(el); });
document.addEventListener('keydown', e => { if (e.key === 'Escape' && !$('#modal').hidden) closeModal(); });

forms.modal = f => { if (modalSubmit) modalSubmit(f); };
acts['close-modal'] = () => closeModal();
acts['toggle-pw'] = el => {
  const input = el.parentElement.querySelector('input');
  const show = input.type === 'password';
  input.type = show ? 'text' : 'password';
  el.setAttribute('aria-pressed', String(show));
  el.setAttribute('aria-label', show ? 'Hide password' : 'Show password');
  el.innerHTML = icon(show ? 'eyeOff' : 'eye', 20);
};
acts.authMode = el => { authMode = el.dataset.mode; render(); };
acts.logout = () => { session = null; authMode = 'login'; gpsPos = null; closeModal(); toast('Signed out.'); render(); };
acts.go = el => go(el.dataset.tab, el.dataset.sub);
acts.sub = el => { sub = el.dataset.sub; render(); };
acts['admin-tab'] = el => { adminTab = el.dataset.tab; window.scrollTo(0, 0); render(); };
acts['admin-filter'] = el => { adminFilter = el.dataset.filter; adminTab = 'records'; window.scrollTo(0, 0); render(); };

function go(t, s) {
  tab = t;
  if (s) sub = s;
  else if (t === 'requests') sub = me()?.role === 'donor' ? 'browse' : 'mine';
  window.scrollTo(0, 0);
  render();
}
function loginAs(id) {
  session = id;
  tab = 'home';
  sub = 'mine';
  adminTab = 'overview';
  gpsPos = null;
  const u = me();
  toast(`Welcome, ${firstName(u)}.`);
  render();
}

/* ============ 6. Auth screens ============ */
const pwToggleFree = () => '';
function viewAuth() {
  const body = authMode === 'register' ? registerForm() : authMode === 'reset' ? resetForm() : loginForm(authMode === 'admin');
  return `<section class="auth">
    <div class="auth-brand">${logo('auth-logo')}</div>
    <div class="auth-card">${body}</div>
    <p class="fine">Prototype build. Data is kept in memory and resets on reload. Not for real medical use.</p>
  </section>`;
}
function loginForm(admin) {
  if (admin) {
    return `<form data-form="admin-login" novalidate class="stack-form">
      <h2>Administrator sign-in</h2>
      <div class="notice warn">${icon('shield', 18)}<p>Authorized administrators only. Activity is logged.</p></div>
      ${field('Email', 'email', { type: 'email', required: true, attrs: 'autocomplete="username"' })}
      ${pwField('Password', 'password')}
      <button class="btn primary block" type="submit">Sign in</button>
      <div class="auth-links"><a href="#" data-act="authMode" data-mode="login">Back to user sign-in</a></div>
    </form>`;
  }
  return `<form data-form="login" novalidate class="stack-form">
    <h2>Sign in</h2>
    ${field('Email', 'email', { type: 'email', required: true, placeholder: 'you@example.com', attrs: 'autocomplete="username"' })}
    ${pwField('Password', 'password')}
    <button class="btn primary block" type="submit">Sign in</button>
    <div class="auth-links">
      <a href="#" data-act="authMode" data-mode="reset">Forgot password?</a>
      <a href="#" data-act="authMode" data-mode="register">Create an account</a>
    </div>
    <div class="demo">
      <a href="#" class="small" data-act="authMode" data-mode="admin">Administrator sign-in</a>
    </div>
  </form>`;
}
function resetForm() {
  return `<form data-form="reset" novalidate class="stack-form">
    <h2>Reset password</h2>
    <p class="notice">Prototype: a production build emails a secure, time-limited reset link. This demo sets the new password directly.</p>
    ${field('Email', 'email', { type: 'email', required: true })}
    ${pwField('New password', 'password', 'At least 8 characters with letters and numbers.')}
    ${pwField('Confirm new password', 'confirm')}
    <button class="btn primary block" type="submit">Update password</button>
    <div class="auth-links"><a href="#" data-act="authMode" data-mode="login">Back to sign-in</a></div>
  </form>`;
}
function registerForm() {
  return `<form data-form="register" novalidate class="stack-form">
    <h2>Create your account</h2>
    <fieldset class="roles"><legend>Account type</legend>
      <label class="role-card"><input type="radio" name="role" value="user" checked data-change="role"><span><strong>Regular user</strong><small>I need blood assistance.</small></span></label>
      <label class="role-card"><input type="radio" name="role" value="donor" data-change="role"><span><strong>Donor</strong><small>I want to help. Requires administrator verification.</small></span></label>
    </fieldset>
    ${field('Full name', 'name', { required: true, attrs: 'autocomplete="name"' })}
    ${field('Email', 'email', { type: 'email', required: true, attrs: 'autocomplete="email"' })}
    ${pwField('Password', 'password', 'At least 8 characters with letters and numbers.')}
    ${pwField('Confirm password', 'confirm')}
    ${field('Mobile number', 'phone', { required: true, placeholder: '0917 000 0000', attrs: 'autocomplete="tel"' })}
    ${bloodSelect('')}
    ${locFields({})}
    <label class="field"><span>Profile picture (optional)</span><input type="file" name="avatar" accept="image/*" data-change="reg-avatar"><small class="hint">Kept in memory for this prototype only.</small></label>
    <div id="donor-box" class="donor-box" hidden>
      <h3>Donor verification</h3>
      <p class="notice">Your account stays pending until an administrator approves your documents. Pending donors do not appear as available donors.</p>
      <label class="field"><span>Verification document <em>*</em></span><input type="file" name="docs" accept=".pdf,.jpg,.jpeg,.png"><small class="hint">The prototype keeps only the file name. Production uses encrypted, restricted storage.</small><small class="err" data-err="docs"></small></label>
      <label class="check"><input type="checkbox" name="donorConsent"> <span>I understand Bloodlink does not replace hospital screening or blood bank eligibility checks.</span></label><small class="err" data-err="donorConsent"></small>
    </div>
    <label class="check"><input type="checkbox" name="terms"> <span>I accept the Terms of Use.</span></label><small class="err" data-err="terms"></small>
    <label class="check"><input type="checkbox" name="privacy"> <span>I have read the Privacy Policy and consent to processing of my data.</span></label><small class="err" data-err="privacy"></small>
    <button class="btn primary block" type="submit">Create account</button>
    <div class="auth-links"><a href="#" data-act="authMode" data-mode="login">Already have an account? Sign in</a></div>
  </form>`;
}
changes.role = el => { const box = $('#donor-box'); if (box) box.hidden = el.value !== 'donor'; };
changes['reg-avatar'] = el => readFile(el.files[0], d => (pendingAvatar = d));

forms.login = f => loginFlow(f, false);
forms['admin-login'] = f => loginFlow(f, true);
async function loginFlow(f, admin) {
  if (!validate(f, [['email', V.email, 'Enter a valid email address.'], ['password', V.req, 'Enter your password.']])) return;
  const email = v(f, 'email').trim().toLowerCase();
  const u = DB.users.find(x => x.email.toLowerCase() === email);
  const ok = !!u && await checkPassword(u, v(f, 'password'));
  if (!ok || (u.role === 'admin') !== admin) return formAlert(f, 'Incorrect email or password.');
  if (u.status === 'pending') return formAlert(f, 'Your account is waiting for administrator approval. Please check back later.');
  if (u.status === 'declined') return formAlert(f, `Your account request was declined${u.verifyNote ? ': ' + u.verifyNote : '.'}`);
  if (u.status === 'suspended') return formAlert(f, `Your account was suspended by an administrator${u.suspendNote ? ': ' + u.suspendNote : '.'} Contact Bloodlink support to resolve this.`);
  loginAs(u.id);
}
forms.reset = async f => {
  if (!validate(f, [
    ['email', V.email, 'Enter a valid email address.'],
    ['password', V.pw, 'Use at least 8 characters with letters and numbers.'],
    ['confirm', (x, f2) => x === v(f2, 'password'), 'Passwords do not match.'],
  ])) return;
  const u = DB.users.find(x => x.email.toLowerCase() === v(f, 'email').trim().toLowerCase());
  if (u && u.role !== 'admin') await setPassword(u, v(f, 'password'));
  toast('If an account exists for that email, its password is updated (prototype).');
  authMode = 'login';
  render();
};
forms.register = async f => {
  const role = v(f, 'role') || f.elements.role?.value || 'user';
  const roleVal = (f.querySelector('input[name="role"]:checked') || {}).value || role;
  if (!validate(f, [
    ['name', V.req, 'Enter your full name.'],
    ['email', V.email, 'Enter a valid email address.'],
    ['email', x => !DB.users.some(u => u.email.toLowerCase() === x.toLowerCase()), 'That email is already registered.'],
    ['password', V.pw, 'Use at least 8 characters with letters and numbers.'],
    ['confirm', (x, f2) => x === v(f2, 'password'), 'Passwords do not match.'],
    ['phone', V.phone, 'Enter a valid mobile number, e.g. 0917 000 0000.'],
    ['bloodType', V.req, 'Choose your blood type.'],
    ['city', V.req, 'Enter your city or municipality.'],
    ['barangay', V.req, 'Enter your barangay.'],
    ['docs', (x, f2) => roleVal !== 'donor' || f2.elements.docs.files.length > 0, 'Upload a verification document.'],
    ['docs', (x, f2) => { const fl = f2.elements.docs.files[0]; return !fl || (fl.size <= 5e6 && /^(image\/(png|jpeg)|application\/pdf)$/.test(fl.type)); }, 'Upload a PDF, JPG, or PNG under 5 MB.'],
    ['donorConsent', x => roleVal !== 'donor' || x === true, 'Confirm the donor consent statement.'],
    ['terms', V.check, 'Accept the Terms of Use to continue.'],
    ['privacy', V.check, 'Accept the Privacy Policy to continue.'],
  ])) return;
  const u = mkUser({
    role: roleVal, status: 'pending', name: v(f, 'name').trim(), email: v(f, 'email').trim(), password: v(f, 'password'),
    phone: v(f, 'phone').trim(), bloodType: v(f, 'bloodType'), loc: readLoc(f), avatar: pendingAvatar,
    verification: roleVal === 'donor' ? 'pending' : 'none',
    docName: roleVal === 'donor' ? f.elements.docs.files[0].name : '',
  });
  await setPassword(u, v(f, 'password'));
  const docFile = roleVal === 'donor' ? f.elements.docs.files[0] : null;
  if (docFile) {
    try { const doc = await readDoc(docFile); DOCS.set(doc.id, doc); u.docId = doc.id; }
    catch (err) { toast(err.message, 'error'); return; }
  }
  pendingAvatar = null;
  DB.users.push(u);
  notify(u.id, roleVal === 'donor' ? 'Registration received. An administrator must approve your account and verify your documents before you can sign in.' : 'Registration received. An administrator must approve your account before you can sign in.');
  audit(`New ${roleVal} account awaiting approval: ${u.name}`);
  toast('Account submitted. You can sign in after an administrator approves it.');
  authMode = 'login';
  render();
};

/* ============ 7. Shells ============ */
function render() {
  saveData();
  pendingMap = null;
  if (map) { map.remove(); map = null; }
  const app = $('#app');
  const u = me();
  if (!u) app.innerHTML = viewAuth();
  else if (u.role === 'admin') app.innerHTML = renderAdmin(u);
  else app.innerHTML = renderUser(u);
  afterRender();
}
function afterRender() {
  if (pendingMap && $('#map')) initMap(pendingMap);
}
function renderUser(u) {
  const unread = DB.notifs.filter(n => n.userId === u.id && !n.read).length;
  const nav = [['home', 'Home', 'home'], ['requests', 'Requests', 'drop'], ['events', 'Events', 'calendar'], ['notifications', 'Notifications', 'bell'], ['me', 'Me', 'user']];
  const views = { home: viewHome, requests: viewRequests, events: viewEvents, notifications: viewNotifications, me: viewMe };
  return `
    <header class="topbar">${logo('brand-logo')}<span class="role-chip">${u.role === 'donor' ? 'Donor' : 'Requester'}</span></header>
    <main class="content" id="main">${verifyBanner(u)}${views[tab](u)}</main>
    <nav class="bottom-nav" aria-label="Main navigation">
      ${nav.map(([id, label, ic]) => `<button class="nav-item ${tab === id ? 'active' : ''}" data-act="go" data-tab="${id}" aria-current="${tab === id ? 'page' : 'false'}">${icon(ic, 24)}${id === 'notifications' && unread ? `<b class="badge-dot">${unread > 9 ? '9+' : unread}</b>` : ''}<span>${label}</span></button>`).join('')}
    </nav>`;
}
const ADMIN_NAV = [['overview', 'Overview', 'home'], ['moderation', 'Posts', 'flag'], ['verify', 'Approvals', 'shield'], ['content', 'Events', 'megaphone'], ['more', 'More', 'users']];
function renderAdmin() {
  const views = { overview: adminOverview, moderation: adminModeration, verify: adminVerify, content: adminContent, users: adminUsers, reports: adminReports, settings: adminSettings, records: adminRecords, more: adminMore };
  const active = ['users', 'reports', 'settings'].includes(adminTab) ? 'more' : adminTab === 'records' ? 'overview' : adminTab;
  return `
    <header class="topbar admin-top">${logo('brand-logo')}<span class="admin-label">${icon('shield', 16)} Admin</span>
      <button class="btn ghost small" data-act="logout">${icon('logout', 18)} Sign out</button></header>
    <main class="admin-main">${(views[adminTab] || adminOverview)()}</main>
    <nav class="bottom-nav admin-bottom" aria-label="Admin navigation">
      ${ADMIN_NAV.map(([id, l, ic]) => `<button class="nav-item ${active === id ? 'active' : ''}" data-act="admin-tab" data-tab="${id}" aria-current="${active === id ? 'page' : 'false'}">${icon(ic, 24)}<span>${l}</span></button>`).join('')}
    </nav>`;
}
function adminMore() {
  const items = [['users', 'Users', 'users'], ['reports', 'Reports', 'alert'], ['settings', 'Settings & audit', 'shield']];
  return `<h1 class="page-title">More</h1><div class="qa-grid">${items.map(([t, l, ic]) => `<button class="qa" data-act="admin-tab" data-tab="${t}">${icon(ic, 24)}<span>${l}</span></button>`).join('')}</div>`;
}

/* ============ 8. Shared components ============ */
const emptyState = (t, x, act = '') => `<div class="empty"><h3>${t}</h3><p>${x}</p>${act}</div>`;
const safetyNote = () => `<aside class="notice safety">${icon('alert', 18)}<p>Bloodlink connects people with potential assistance. It does not guarantee donor eligibility, blood availability, compatibility, or medical outcomes. Donation or transfusion must follow hospital screening by a licensed blood bank and qualified medical staff.</p></aside>`;
function verifyBanner(u) {
  if (u.role !== 'donor') return '';
  if (u.verification === 'pending') return `<div class="notice warn">${icon('clock', 18)}<p>Your donor verification is pending administrator review. You will not appear as an available donor until it is approved.</p></div>`;
  if (u.verification === 'declined') return `<div class="notice danger">${icon('alert', 18)}<p>Your donor verification was declined${u.verifyNote ? `: ${esc(u.verifyNote)}` : ''}. Contact Bloodlink support to resolve this.</p></div>`;
  return '';
}
function requestCard(p, viewer, actions = '') {
  const mine = viewer.id === p.authorId;
  const involved = mine || p.offers.some(o => o.donorId === viewer.id);
  return `<article class="card post">
    <header class="post-top">
      <span class="blood">${esc(p.bloodType)}</span>
      <div class="post-badges">${isUrgent(p) && ACTIVE_REQ.includes(p.status) ? '<span class="badge b-urgent">Urgent</span>' : ''}${statusBadge(p.status)}</div>
    </header>
    <h3>${mine ? esc(p.patient) : 'Blood assistance request'}</h3>
    <ul class="meta">
      <li>${icon('pin', 16)} ${esc(mine ? placeText(p.loc) : publicPlace(p.loc))}</li>
      <li>${icon('clock', 16)} Needed by ${fmt(p.neededBy)}</li>
      ${p.units ? `<li>${icon('drop', 16)} ${p.units} unit(s) requested</li>` : ''}
    </ul>
    ${involved ? `<p class="small"><strong>Hospital:</strong> ${esc(p.hospital)}<br><strong>Contact:</strong> ${esc(p.contact)}</p>` : '<p class="small muted">Hospital and contact details are shared with donors who offer assistance.</p>'}
    ${p.description ? `<p>${esc(p.description)}</p>` : ''}
    ${p.status === 'correction' ? `<p class="notice warn small">Correction requested: ${esc(p.note)}</p>` : ''}
    ${p.status === 'declined' ? `<p class="notice danger small">Declined: ${esc(p.reason)}</p>` : ''}
    ${mine && p.offers.length ? `<p class="small muted">${p.offers.length} donor offer(s)</p>` : ''}
    ${actions ? `<footer class="actions">${actions}</footer>` : ''}
  </article>`;
}
function availSummary(p) {
  const d = userById(p.authorId);
  return `<article class="card donor"><header class="post-top"><span class="blood">${esc(p.bloodType)}</span><span class="badge b-approved">${icon('check', 14)} Verified</span></header>
    <h3>${esc(shortName(d))}</h3><p class="meta">${icon('pin', 16)} ${esc(publicPlace(p.loc))} · ${p.radius} km radius</p></article>`;
}
function eventCard(p) {
  return `<article class="card"><h3>${esc(p.title)}</h3><ul class="meta">
    <li>${icon('calendar', 16)} ${fmt(p.eventDate)}</li><li>${icon('pin', 16)} ${esc(p.venue)}${p.loc?.city ? ` · ${esc(publicPlace(p.loc))}` : ''}</li></ul>
    <p>${esc(p.description)}</p></article>`;
}

/* ============ 9. User: Home, Requests, Events, Notifications, Me ============ */
function viewHome(u) {
  const isDonor = u.role === 'donor';
  const quick = isDonor
    ? [['requests', 'browse', 'drop', 'Browse requests'], ['requests', 'availability', 'pin', 'My availability'], ['events', '', 'calendar', 'Events']]
    : [['requests', 'new', 'plus', 'New request'], ['requests', 'find', 'search', 'Find donors'], ['events', '', 'calendar', 'Events']];
  const picks = isDonor
    ? DB.posts.filter(p => p.type === 'request' && ACTIVE_REQ.includes(p.status))
    : DB.posts.filter(p => p.type === 'availability' && p.status === 'approved' && p.availability !== 'unavailable');
  const news = DB.posts.filter(p => p.type === 'announcement' && p.status === 'approved');
  return `
    <section class="hero"><p class="eyebrow">${isDonor ? 'Donor' : 'Requester'} dashboard</p><h1>Hello, ${esc(firstName(u))}</h1>
      <p>${isDonor ? 'Thank you for being ready to help.' : 'Blood assistance is one request away.'}</p></section>
    <div class="qa-grid">${quick.map(([t, s, ic, l]) => `<button class="qa" data-act="go" data-tab="${t}" ${s ? `data-sub="${s}"` : ''}>${icon(ic, 24)}<span>${l}</span></button>`).join('')}</div>
    <h2 class="section-title">${isDonor ? 'Open requests' : 'Available donors'}</h2>
    ${picks.length ? `<div class="stack">${picks.slice(0, 3).map(p => (isDonor ? requestCard(p, u) : availSummary(p))).join('')}</div>` : emptyState('Nothing here yet', isDonor ? 'No approved requests right now.' : 'No approved donor listings yet.')}
    <h2 class="section-title">Announcements</h2>
    ${news.length ? news.map(n => `<article class="card"><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p></article>`).join('') : emptyState('No announcements', 'Important updates from administrators appear here.')}
    ${safetyNote()}`;
}
function viewRequests(u) {
  const isDonor = u.role === 'donor';
  const subs = isDonor
    ? [['browse', 'Browse requests'], ['availability', 'My availability'], ['messages', 'Messages']]
    : [['mine', 'My requests'], ['find', 'Find donors'], ['new', 'New request']];
  if (!subs.some(s => s[0] === sub)) sub = subs[0][0];
  const body = isDonor
    ? { browse: donorBrowse, availability: donorAvailability, messages: donorMessages }[sub](u)
    : { mine: userMine, find: userFind, new: userNew }[sub](u);
  return `<h1 class="page-title">Requests</h1>
    <div class="seg" role="tablist">${subs.map(([id, l]) => `<button role="tab" class="${sub === id ? 'on' : ''}" aria-selected="${sub === id}" data-act="sub" data-sub="${id}">${l}</button>`).join('')}</div>
    ${body}`;
}
function userMine(u) {
  const mine = DB.posts.filter(p => p.type === 'request' && p.authorId === u.id).sort((a, b) => b.createdAt.localeCompare(a.createdAt));
  if (!mine.length) return emptyState('No requests yet', 'Submit a blood assistance request. Administrators review every request before donors can see it.', `<button class="btn primary" data-act="sub" data-sub="new">${icon('plus', 18)} New request</button>`);
  return `<div class="stack">${mine.map(p => requestCard(p, u, ownerActions(p))).join('')}</div>
    <h2 class="section-title">Conversations</h2>${convoList(u)}`;
}
function ownerActions(p) {
  const closed = ['closed', 'fulfilled'].includes(p.status);
  const b = [];
  if (!closed) b.push(`<button class="btn ghost small" data-act="edit-req" data-id="${p.id}">${icon('edit', 16)} Edit</button>`);
  if (['assistance_offered', 'in_progress'].includes(p.status)) b.push(`<button class="btn primary small" data-act="fulfill" data-id="${p.id}">${icon('check', 16)} Mark fulfilled</button>`);
  if (!closed) b.push(`<button class="btn ghost small danger-text" data-act="cancel-req" data-id="${p.id}">${icon('x', 16)} Cancel</button>`);
  p.offers.forEach(o => { const d = userById(o.donorId); if (d) b.push(`<button class="btn ghost small" data-act="thread" data-id="${p.id}" data-other="${d.id}">${icon('message', 16)} ${esc(shortName(d))}</button>`); });
  return b.join('');
}
function requestFields(p = {}) {
  return `
    ${field('Patient or requester name', 'patient', { required: true, value: p.patient || '' })}
    <div class="grid-2">
      <label class="field"><span>Blood type <em>*</em></span><select name="bloodType"><option value="">Choose…</option>${opt(BLOOD_TYPES, p.bloodType || '')}</select><small class="err" data-err="bloodType"></small></label>
      ${field('Units needed', 'units', { type: 'number', value: p.units || '', attrs: 'min="1" step="1"', hint: 'Optional' })}
    </div>
    ${field('Hospital or treatment location', 'hospital', { required: true, value: p.hospital || '' })}
    ${locFields(p.loc || {})}
    <div class="grid-2">
      ${field('Needed by', 'neededBy', { type: 'datetime-local', required: true, value: p.neededBy ? localInput(p.neededBy) : '', attrs: `min="${localInput()}"` })}
      ${field('Contact number', 'phone', { required: true, value: p.contact || me()?.phone || '', placeholder: '0917 000 0000' })}
    </div>
    ${field('Situation (optional)', 'description', { type: 'textarea', value: p.description || '', placeholder: 'Only what donors need to know' })}
    <label class="field"><span>Patient photo (optional)</span><input type="file" name="photo" accept="image/*"><small class="hint">Upload only with the patient's consent. Kept in memory for this prototype; only administrators can view it.</small></label>
    <label class="check"><input type="checkbox" name="photoConsent"> <span>The patient or their guardian consented to this photo being reviewed.</span></label><small class="err" data-err="photoConsent"></small>`;
}
function userNew() {
  return `<section class="card"><h2>New assistance request</h2><p class="small muted">Every request is reviewed by an administrator before donors can see it.</p>
    <form data-form="request" novalidate class="stack-form">${requestFields()}<button class="btn primary block" type="submit">Submit for review</button></form></section>${safetyNote()}`;
}
forms.request = f => saveRequest(f, null);
acts['edit-req'] = el => {
  const p = postById(el.dataset.id);
  if (!p) return;
  openModal('Edit request', requestFields(p), { label: 'Save & resubmit', submit: f => saveRequest(f, p.id) });
};
async function saveRequest(f, id) {
  if (!validate(f, [
    ['patient', V.req, 'Enter the patient or requester name.'],
    ['bloodType', V.req, 'Choose a blood type.'],
    ['units', V.pos, 'Units must be at least 1, or leave blank.'],
    ['hospital', V.req, 'Enter the hospital or treatment location.'],
    ['city', V.req, 'Enter the city or municipality.'],
    ['barangay', V.req, 'Enter the barangay.'],
    ['neededBy', V.future, 'Choose a future date and time.'],
    ['phone', V.phone, 'Enter a valid mobile number, e.g. 0917 000 0000.'],
    ['photoConsent', (x, f2) => !f2.elements.photo.files.length || x === true, 'Confirm consent before uploading a patient photo.'],
  ])) return false;
  const existing = id ? postById(id) : null;
  const file = f.elements.photo?.files[0];
  let photo = null;
  if (file) {
    try { photo = await readDoc(file); }
    catch (_) { return formAlert(f, 'Could not read the photo. Try another image.'); }
  }
  const data = {
    patient: v(f, 'patient').trim(), bloodType: v(f, 'bloodType'), units: v(f, 'units') ? Number(v(f, 'units')) : null,
    hospital: v(f, 'hospital').trim(), loc: readLoc(f), neededBy: new Date(v(f, 'neededBy')).toISOString(),
    contact: v(f, 'phone').trim(), description: v(f, 'description').trim(),
    // A new photo replaces the old one; otherwise the existing photo is kept.
    photoName: photo ? photo.name : (existing?.photoName || ''),
    photoId: photo ? photo.id : (existing?.photoId || null),
  };
  if (photo) { PHOTOS.set(photo.id, photo); if (existing?.photoId) PHOTOS.delete(existing.photoId); }
  const u = me();
  if (id) {
    const p = postById(id);
    Object.assign(p, data, { status: 'pending', note: '' });
    audit(`${u.name} edited request ${p.id}; resubmitted for review`);
    toast('Changes submitted for review.');
  } else {
    DB.posts.unshift(mkPost({ type: 'request', authorId: u.id, ...data }));
    audit(`${u.name} submitted a request for review`);
    toast('Request submitted for administrator review.');
  }
  notify(u.id, 'Your request is pending administrator review.');
  tab = 'requests';
  sub = 'mine';
  closeModal();
  render();
  return true;
}
