function userFind(u) {
  const origin = gpsPos || cityCoords(u.loc) || [14.5995, 120.9842];
  const list = nearbyDonors(u, donorFilter, origin);
  pendingMap = {
    origin, gps: !!gpsPos,
    markers: list.filter(x => x.d.privacy.shareLocation).map(x => ({ pos: x.pos, name: shortName(x.d), bt: x.p.bloodType, city: publicPlace(x.p.loc) })),
  };
  const options = ['', ...BLOOD_TYPES].map(b => `<option value="${b}" ${b === donorFilter ? 'selected' : ''}>${b || 'Any blood type'}</option>`).join('');
  return `
    <div class="toolbar">
      <label class="field"><span>Blood type</span><select data-change="donor-filter">${options}</select></label>
      <button class="btn ghost small" data-act="gps">${icon('pin', 16)} Use my GPS</button>
    </div>
    <div id="map" class="map" role="region" aria-label="Map of available donors"></div>
    <p class="small muted">Pins show approximate city-level positions only, and only for donors who agreed to location sharing. GPS is used for this view and not stored.</p>
    ${list.length ? `<div class="stack">${list.map(x => donorCard(x, u)).join('')}</div>` : emptyState('No donors found', 'Try another blood type, or check back later.')}
    ${safetyNote()}`;
}
function nearbyDonors(u, bt, origin) {
  return DB.posts
    .filter(p => p.type === 'availability' && p.status === 'approved' && p.availability !== 'unavailable')
    .filter(p => { const d = userById(p.authorId); return d && canDonate(d) && d.id !== u.id && !u.blocked.includes(d.id); })
    .filter(p => !bt || p.bloodType === bt)
    .map(p => { const d = userById(p.authorId); const pos = approxPos(p.loc, p.authorId); return { p, d, pos, km: kmBetween(origin, pos) }; })
    .sort((a, b) => a.km - b.km);
}
changes['donor-filter'] = el => { donorFilter = el.value; render(); };
